<template><view class="page"><view class="hero"><text class="eyebrow">真实体验计划</text><text class="title">先体验，再决定</text><text class="copy">参与慢π活动关联的体验项目，用真实反馈帮助我们筛选值得长期合作的产品与服务。</text></view><view class="topline"><view><text class="section-title">开放中的项目</text><text class="section-copy">名额、活动和审核状态都会清楚展示</text></view><text class="mine-link" @click="openMine">我的体验 ›</text></view><LoadingState v-if="loading" title="正在加载体验项目" description="正在同步开放项目。" /><EmptyState v-else-if="error" variant="error" title="体验项目加载失败" :description="error" action-text="重新加载" @action="load" /><EmptyState v-else-if="!rows.length" variant="activity" title="暂时没有开放项目" description="新的体验项目开放后，会在这里展示。" /><view v-else class="list"><view v-for="item in rows" :key="item.id" class="card"><view class="card-head"><view><text class="card-title">{{ item.title }}</text><text class="activity" v-if="item.activity">关联活动：{{ item.activity.title }}</text></view><text class="open">开放中</text></view><text class="description">{{ item.description || '参与体验并提交真实反馈，帮助活动方持续改进。' }}</text><view class="meta"><text>剩余 {{ item.remaining < 0 ? '不限' : item.remaining }} 个名额</text><text v-if="item.applyDeadline">申请截止 {{ dateText(item.applyDeadline) }}</text></view><button class="primary" :disabled="submitting === item.id" @click="apply(item)">{{ submitting === item.id ? '提交中…' : '申请体验' }}</button></view></view><view class="bottom-space" /></view></template>
<script setup lang="ts">import { onShow } from '@dcloudio/uni-app';import { ref } from 'vue';import EmptyState from '../../components/EmptyState.vue';import LoadingState from '../../components/LoadingState.vue';import { ensureUser,request,withTenantCode } from '../../api';const rows=ref<any[]>([]),loading=ref(true),error=ref(''),submitting=ref(0);function dateText(v?:string){return v?v.slice(0,16).replace('T',' '):''}async function load(){loading.value=true;error.value='';try{rows.value=await request<any[]>('/public/experiences')}catch(e:any){error.value=e?.message||'体验项目加载失败'}finally{loading.value=false}}async function apply(item:any){if(submitting.value)return;try{await ensureUser()}catch{return}submitting.value=item.id;try{await request(`/public/experiences/${item.id}/apply`,{method:'POST',data:{}});uni.showModal({title:'申请已提交',content:'运营审核通过后，你可以在“我的体验”中提交反馈。',showCancel:false})}catch(e:any){uni.showToast({title:e?.message||'申请失败',icon:'none'})}finally{submitting.value=0}}function openMine(){uni.navigateTo({url:withTenantCode('/pages/experience/mine')})}onShow(load)</script>
<style scoped>.page{min-height:100vh;background:#f5f7f5;color:#18251e;padding-bottom:env(safe-area-inset-bottom);font-family:-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif}.hero{margin:24rpx 28rpx 0;padding:34rpx 30rpx;border-radius:16rpx;background:#16252d;color:#fff}.eyebrow{display:block;color:#bce8ca;font-size:22rpx;font-weight:800}.title{display:block;margin-top:14rpx;font-size:42rpx;font-weight:900}.copy{display:block;margin-top:16rpx;color:rgba(255,255,255,.76);font-size:24rpx;line-height:1.65}.topline{display:flex;align-items:end;justify-content:space-between;padding:34rpx 28rpx 18rpx}.section-title,.section-copy{display:block}.section-title{font-size:32rpx;font-weight:900}.section-copy{margin-top:7rpx;color:#748079;font-size:22rpx}.mine-link{color:#08753f;font-size:24rpx;font-weight:800}.list{display:grid;gap:16rpx;padding:0 28rpx}.card{padding:26rpx;border:1rpx solid #e0e8e3;border-radius:16rpx;background:#fff}.card-head{display:flex;justify-content:space-between;gap:16rpx}.card-title{display:block;font-size:29rpx;font-weight:900}.activity{display:block;margin-top:7rpx;color:#748079;font-size:22rpx}.open{flex:none;height:40rpx;padding:6rpx 12rpx;border-radius:8rpx;background:#e8f7ed;color:#08753f;font-size:21rpx}.description{display:block;margin-top:18rpx;color:#44534b;font-size:24rpx;line-height:1.6}.meta{display:flex;flex-wrap:wrap;gap:18rpx;margin-top:18rpx;color:#758078;font-size:22rpx}.primary{width:100%;height:72rpx;margin-top:22rpx;border:0;border-radius:12rpx;background:#08753f;color:#fff;font-size:26rpx;font-weight:800}.primary::after{border:0}.primary[disabled]{opacity:.55}.state{display:grid;gap:12rpx;margin:0 28rpx;padding:36rpx;border-radius:16rpx;background:#fff;color:#748079;text-align:center;font-size:24rpx}.state.error{color:#b42318}.empty-title{color:#24342b;font-size:28rpx;font-weight:900}.link-button{border:0;background:transparent;color:#08753f;font-size:24rpx}.bottom-space{height:50rpx}</style>
